    private static final String DEFAULT_QUERY =
            "SELECT id, name, email FROM users ORDER BY id";

    private App() {
    }

    public static void main(String[] args) {
        String sql = args.length > 0 ? String.join(" ", args) : DEFAULT_QUERY;
